const previewReleaseHistory=[{"date": "2026-10-04", "changes": ["Làm gọn giao diện đặt cơm, quán ăn và quản lý menu trên điện thoại và máy tính", "Chọn quán khi đăng menu, ghi nhận từng món riêng cho mỗi quán", "Đánh giá từng món bằng sao, gợi ý cảm nhận phù hợp với món và ghi chú tự do", "Xem lịch sử ăn theo lịch tháng và theo dõi riêng các đơn chưa thanh toán", "Dùng lại menu, sửa danh sách món, đánh dấu hết món và xuất danh sách đặt cơm", "Giữ món đã chọn khi đăng nhập và cập nhật danh sách mới nhất trước khi sao chép chốt đơn"]}, {"date": "2026-08-19", "changes": ["Người đăng cơm có thể chốt đơn (bấm nút copy danh sách sẽ tự khoá nhận món), và mở lại khi cần", "Khi đơn đã chốt, mọi người không đặt/sửa món qua app được nữa, chỉ có thể liên hệ trực tiếp người đăng cơm"]}, {"date": "2026-07-08", "changes": ["Thêm nút tải mã QR chuyển khoản (VietQR & MoMo) về máy", "Sửa bố cục màn hình quét QR bị vỡ trên điện thoại, thông tin chuyển khoản hiển thị gọn gàng hơn", "Sửa lỗi nút đặt món bị che trên điện thoại"]}, {"date": "2026-07-01", "changes": ["Tiếp tục fix bug", "Ảnh preview khi share link lên Slack hiển thị nhanh hơn", "Người đăng menu có thể thống kê được tổng số lượng món cần mua", "Người mua có thể xem được chi tiết món mua của mình trong màn hình quét QR Code", "Fix bug"]}, {"date": "2026-06-30", "changes": ["Thêm trang \"Menu của tôi\": xem lại menu đã đăng, số đơn, số người đã trả, chỉnh sửa hoặc xoá nhanh"]}, {"date": "2026-06-28", "changes": ["Tự động tạo mã QR chuyển khoản động (điền sẵn số tiền và nội dung) dựa theo cấu hình trong Hồ sơ của người đăng thực đơn", "Đồng bộ danh sách người đang xem và món ăn đang được chọn của các user khác trong menu", "Cập nhật realtime cho tính năng menu: giờ đây bạn có thể xem được ai đang xem thực đơn cùng bạn, và dồng nghiệp đang phân vân nên chọn món nào", "Màu của món ăn sẽ đậm hơn khi nhiều người cùng đang muốn chọn món đó"]}, {"date": "2026-06-26", "changes": ["Cập nhật OCR trích xuất thông tin món ăn từ ảnh ", "Chọn nhanh món ăn bằng cách bấm chọn trực tiếp từ thực đơn AI", "Tạo ảnh menu xem trước khi chia sẻ link (og-image) trên Slack", "Sửa lỗi bố cục hiển thị ảnh thực đơn và căn chỉnh giao diện rõ đẹp hơn"]}, {"date": "2026-06-23", "changes": ["Thêm hiển thị version ở footer, click vào xem danh sách cập nhật", "Lịch sử đơn có thể click vào để xem chi tiết menu", "Ô nhập món đặt hỗ trợ nhiều dòng", "Có thể sửa lại đơn đã đặt, hiện dấu 'đã sửa lúc HH:mm' cho mọi người thấy"]}];
(() => {
'use strict';
let read=false,showAll=false;
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const style=document.createElement('style');style.textContent=`.release-list{list-style:none;padding:0;margin:24px 0}.release-entry{margin:0 0 22px;padding:0 0 0 20px;border-left:2px solid #cbd7c8}.release-entry h2{margin:8px 0 12px;font-size:21px}.release-entry li{padding:5px 0;color:#435c49}.release-date{font-size:13px;color:#1f6e45;font-weight:700}.release-note{padding:12px 16px;border-radius:12px;background:#e7f1e5;color:#31513b;font-size:14px}.release-modal{max-width:600px}.release-modal .release-list{margin-top:16px}.release-modal header{padding:0 0 16px}.release-modal ul:not(.release-list){padding-left:20px}.ui-updates{position:relative;min-width:44px;width:44px;padding:10px}.ui-unread{position:absolute;right:8px;top:7px;width:7px;height:7px;background:#1f6e45;border-radius:50%;box-shadow:0 0 0 2px white}@media(max-width:640px){.nav .ui-updates{display:inline-flex!important}.release-entry{padding-left:14px}.release-modal{width:calc(100% - 24px);max-height:calc(100dvh - 24px);padding:20px}}`;document.head.append(style);
const list=entries=>'<ol class="release-list">'+entries.map((entry,i)=>'<li class="release-entry"><time class="release-date" datetime="'+entry.date+'">'+entry.date.split('-').reverse().join('/')+'</time>'+(i===0?'<span class="badge" style="margin-left:10px">Mới nhất trong lịch sử mẫu</span>':'')+'<h2>'+(['2026-10-04'].includes(entry.date)?'Đặt món, lịch cơm và đánh giá':'Cập nhật trải nghiệm')+'</h2><ul>'+entry.changes.map(c=>'<li>'+esc(c)+'</li>').join('')+'</ul></li>').join('')+'</ol>';
const dialog=document.createElement('dialog');dialog.className='modal release-modal';dialog.setAttribute('aria-labelledby','release-title');document.body.append(dialog);
window.previewChangelogRead=()=>read;
const markRead=()=>{read=true;document.querySelectorAll('.ui-unread').forEach(d=>d.remove())};
window.openChangelogPreview=()=>{
markRead();dialog.innerHTML='<header><div><span class="eyebrow">Có gì mới</span><h2 id="release-title">Cập nhật Cơm Trưa</h2></div><button class="close" aria-label="Đóng changelog">×</button></header><p class="release-note">Đang xem mẫu thiết kế. Nội dung lấy từ lịch sử trong mã nguồn, không xác nhận phiên bản app đang chạy.</p>'+list(previewReleaseHistory.slice(0,1))+'<button class="green" data-release-all style="width:100%">Xem tất cả cập nhật</button>';
dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelector('[data-release-all]').onclick=()=>{dialog.close();go('changelog')};dialog.showModal();
};
window.renderChangelogPreview=root=>{
markRead();root.innerHTML=pageHeader('Cập nhật Cơm Trưa','Lịch sử cập nhật','')+'<p class="release-note">Bản xem trước giao diện changelog. Nội dung từ lịch sử mã nguồn; thay đổi thiết kế hiện tại đang chờ bạn duyệt.</p>'+list(showAll?previewReleaseHistory:previewReleaseHistory.slice(0,3))+'<button data-release-toggle>'+(showAll?'Thu gọn lịch sử':'Xem các cập nhật trước đó')+'</button>';
root.querySelector('[data-release-toggle]').onclick=()=>{showAll=!showAll;window.renderChangelogPreview(root)};
};
})();
